# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::AlertSignals do
  # "The task gathers real signals: the monolith's own counters, and Timekeeping's write latency, write counts
  # and `503 reference_unavailable` counts from its `GET /internal/v1/metrics` endpoint, read with the service identity."
  it "gathers per-company outbox lag, pending intent age and stale_generation counts from real rows and the metrics body" do
    TimekeepingOwnership.ensure_initial!
    now = Time.utc(2026, 3, 3, 12, 7)
    connection = ActiveRecord::Base.connection
    insert_outbox = lambda do |company_id, created_at, sent_at|
      connection.execute(ActiveRecord::Base.sanitize_sql_array([
        "INSERT INTO entry_outbox_items (company_id, entry_id, generation, payload, created_at, sent_at) " \
        "VALUES (?, 1, 1, '{}'::jsonb, ?, ?)", company_id, created_at, sent_at
      ]))
    end
    insert_outbox.call(7, now - 400, nil)
    insert_outbox.call(7, now - 100, nil)
    insert_outbox.call(9, now - 3600, now - 3500)
    InvoiceOperationIntent.create!(company_id: 7, invoice_id: 1, operation_id: SecureRandom.uuid, generation: 1,
                                   state: "pending", created_at: now - 700)
    InvoiceOperationIntent.create!(company_id: 9, invoice_id: 2, operation_id: SecureRandom.uuid, generation: 1,
                                   state: "committed", created_at: now - 9000)
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [{ "company_id" => 7, "windows" => [
        { "window_start" => "2026-03-03T12:00:00Z", "writes" => 5, "reference_unavailable" => 0,
          "stale_generation" => 2, "latency_ms_sum" => 50, "latency_ms_buckets" => { "25" => 5 } },
        { "window_start" => "2026-03-03T12:05:00Z", "writes" => 3, "reference_unavailable" => 0,
          "stale_generation" => 1, "latency_ms_sum" => 30, "latency_ms_buckets" => { "25" => 3 } }
      ] }]
    }
    metrics_client = Struct.new(:body) { def fetch = body }.new(body)

    signals = described_class.gather(now:, metrics_client:)

    expect(signals.outbox_lag_seconds_by_company).to eq(7 => 400)
    expect(signals.pending_intent_age_seconds_by_company).to eq(7 => 700)
    expect(signals.stale_generation_outside_handoff_by_company).to eq(7 => 3)
    expect(signals.write_metrics).to eq(body)
    expect(signals.now).to eq(now)
    expect([signals.prepare_refusals_by_company, signals.unexplained_reconciliation_differences_by_company,
            signals.financial_snapshot_changes_by_company, signals.write_pause_seconds]).to all(be_nil)
  end
end
